function write_tables(T, name, caption)
%WRITE_TABLES  Save a results table as CSV and LaTeX (booktabs) in results/.
assert(contains(caption,'imulat'),'Table caption must state Simulation/Simulated.');
rdir = fullfile(fileparts(mfilename('fullpath')),'results');
if ~exist(rdir,'dir'), mkdir(rdir); end
writetable(T, fullfile(rdir,[name '.csv']));
fid = fopen(fullfile(rdir,[name '.tex']),'w');
nc = width(T);
fprintf(fid,'%% %s\n\\begin{table}[htbp]\n\\centering\n\\caption{%s}\n\\label{tab:%s}\n\\small\n', ...
    'auto-generated by write_tables.m', caption, name);
fprintf(fid,'\\begin{tabular}{l%s}\n\\toprule\n', repmat('r',1,nc-1));
hdr = strrep(T.Properties.VariableNames,'_','\_');
fprintf(fid,'%s \\\\\n\\midrule\n', strjoin(hdr,' & '));
for i = 1:height(T)
    c = cell(1,nc);
    for j = 1:nc
        v = T{i,j};
        if iscell(v), v = v{1}; end
        if isstring(v) || ischar(v), c{j} = strrep(char(v),'_','\_');
        elseif isnan(v), c{j} = '--';
        elseif abs(v) >= 1000 || (abs(v) < 0.01 && v ~= 0), c{j} = sprintf('%.3g',v);
        else, c{j} = sprintf('%.2f',v);
        end
    end
    fprintf(fid,'%s \\\\\n', strjoin(c,' & '));
end
fprintf(fid,'\\bottomrule\n\\end{tabular}\n\\end{table}\n');
fclose(fid);
end
